 * Prefix index over Unicode strings.
 *
 * Stores words in a real trie: one node per distinct prefix, walked by
 * Unicode code point so that a character outside the basic multilingual
 * plane is a single step rather than a pair of surrogate halves. Every
 * listing is ordered by code point. Each node keeps a running count of the
 * words stored below it so that `countPrefix` costs only the length of the
 * prefix.
 */

class Node {
  constructor() {
    /** @type {Map<string, Node>} Children keyed by the single code point they represent. */
    this.children = new Map();
    /** @type {boolean} True when a word ends at this node. */
    this.isEnd = false;
    /** @type {unknown} Value stored when isEnd is true. */
    this.value = undefined;
    /** @type {number} Number of words stored in the subtree rooted here, this node included. */
    this.count = 0;
  }
}

/**
 * Splits a string into an array of single code point strings.
 * @param {string} value String to split.
 * @returns {string[]} Code points, one per array entry.
 */
function toCodePoints(value) {
  return Array.from(value);
}

/**
 * Sorts an array of single code point strings in place, by code point value.
 * @param {string[]} keys Code point strings to sort.
 * @returns {string[]} The same array, sorted.
 */
function sortByCodePoint(keys) {
  return keys.sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
}

export class Trie {
  /** @type {Node} */
  #root = new Node();

  /** @type {number} Number of stored words. */
  #size = 0;

  /** @type {number} Number of nodes, the root included. */
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const codePoints = toCodePoints(word);
    let node = this.#root;
    const path = [node];
    for (const cp of codePoints) {
      let child = node.children.get(cp);
      if (!child) {
        child = new Node();
        node.children.set(cp, child);
        this.#nodeCount += 1;
      }
      node = child;
      path.push(node);
    }
    const wasEnd = node.isEnd;
    const previous = node.value;
    node.isEnd = true;
    node.value = value;
    if (!wasEnd) {
      this.#size += 1;
      for (const n of path) n.count += 1;
    }
    return wasEnd ? previous : undefined;
  }

  /**
   * Finds the node for a word, or undefined when the path does not exist.
   * @param {string} word Word to look up.
   * @returns {Node | undefined} Terminal node, or undefined.
   */
  #findNode(word) {
    let node = this.#root;
    for (const cp of toCodePoints(word)) {
      node = node.children.get(cp);
      if (!node) return undefined;
    }
    return node;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#findNode(word);
    return node && node.isEnd ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#findNode(word);
    return Boolean(node && node.isEnd);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const codePoints = toCodePoints(word);
    let node = this.#root;
    const path = [node];
    for (const cp of codePoints) {
      node = node.children.get(cp);
      if (!node) return false;
      path.push(node);
    }
    if (!node.isEnd) return false;
    node.isEnd = false;
    node.value = undefined;
    this.#size -= 1;
    for (const n of path) n.count -= 1;
    for (let i = path.length - 1; i > 0; i -= 1) {
      const current = path[i];
      if (current.count === 0) {
        const parent = path[i - 1];
        parent.children.delete(codePoints[i - 1]);
        this.#nodeCount -= 1;
      } else {
        break;
      }
    }
    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
    const node = this.#findNode(prefix);
    return node ? node.count : 0;
  }

  /**
   * Collects words in code point order from a node, up to a limit.
   * @param {Node} node Node to start from.
   * @param {string} prefix Prefix accumulated to reach the node.
   * @param {number} limit Maximum number of words to collect.
   * @param {Array<[string, unknown]>} out Accumulator for [word, value] pairs.
   */
  #collect(node, prefix, limit, out) {
    if (out.length >= limit) return;
    if (node.isEnd) {
      out.push([prefix, node.value]);
      if (out.length >= limit) return;
    }
    const keys = sortByCodePoint([...node.children.keys()]);
    for (const key of keys) {
      this.#collect(node.children.get(key), prefix + key, limit, out);
      if (out.length >= limit) return;
    }
  }

  /**
   * Validates a limit argument.
   * @param {number} limit Limit to validate.
   * @returns {void}
   */
  #checkLimit(limit) {
    const valid = limit === Number.POSITIVE_INFINITY
      || (Number.isSafeInteger(limit) && limit >= 0);
    if (!valid) throw new TypeError('limit must be a non-negative integer');
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
    this.#checkLimit(limit);
    const node = this.#findNode(prefix);
    if (!node || limit === 0) return [];
    const out = [];
    this.#collect(node, prefix, limit, out);
    return out.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const out = [];
    this.#collect(this.#root, '', Number.POSITIVE_INFINITY, out);
    return out;
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    if (typeof text !== 'string') throw new TypeError('text must be a string');
    let node = this.#root;
    let best = null;
    let consumed = '';
    if (node.isEnd) best = { word: '', value: node.value };
    for (const cp of toCodePoints(text)) {
      node = node.children.get(cp);
      if (!node) break;
      consumed += cp;
      if (node.isEnd) best = { word: consumed, value: node.value };
    }
    return best;
  }
}
"}

