  if (typeof word !== 'string') throw new TypeError('word must be a string');
  const codePoints = toCodePoints(word);
  let node = this.#root;
  const path = [node];
  for (const cp of codePoints) {
    let child = node.children.get(cp);
    if (!child) {
      child = new Node();
      node.children.set(cp, child);
      this.#nodeCount += 1;
    }
    node = child;
    path.push(node);
  }
  const wasEnd = node.isEnd;
  const previous = node.value;
  node.isEnd = true;
  node.value = value;
  if (!wasEnd) {
    this.#size += 1;
    for (const n of path) n.count += 1;
  }
  return wasEnd ? previous : undefined;
}

/**
 * Finds the node for a word, or undefined when the path does not exist.
 * @param {string} word Word to look up.
 * @returns {Node | undefined} Terminal node, or undefined.
 */
#findNode(word) {
  let node = this.#root;
  for (const cp of toCodePoints(word)) {
    node = node.children.get(cp);
    if (!node) return undefined;
  }
  return node;
}

/**
 * Reads the value stored under a word.
 * @param {string} word Word to look up.
 * @returns {unknown} Stored value, or undefined when the word is absent.
 */
