  if (typeof word !== 'string') throw new TypeError('word must be a string');
  const codePoints = toCodePoints(word);
  let node = this.#root;
  const path = [node];
  for (const cp of codePoints) {
    node = node.children.get(cp);
    if (!node) return false;
    path.push(node);
  }
  if (!node.isEnd) return false;
  node.isEnd = false;
  node.value = undefined;
  this.#size -= 1;
  for (const n of path) n.count -= 1;
  for (let i = path.length - 1; i > 0; i -= 1) {
    const current = path[i];
    if (current.count === 0) {
      const parent = path[i - 1];
      parent.children.delete(codePoints[i - 1]);
      this.#nodeCount -= 1;
    } else {
      break;
    }
  }
  return true;
}

