  if (out.length >= limit) return;
  if (node.isEnd) {
    out.push([prefix, node.value]);
    if (out.length >= limit) return;
  }
  const keys = sortByCodePoint([...node.children.keys()]);
  for (const key of keys) {
    this.#collect(node.children.get(key), prefix + key, limit, out);
    if (out.length >= limit) return;
